import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = ""
    for ch in ref:
        if ch.isalpha():
            letters += ch
        else:
            break
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord("A") + 1)
    return idx - 1

def row_idx(ref):
    return int("".join(ch for ch in ref if ch.isdigit())) - 1

wb = zipfile.ZipFile("budget.xlsx")
print("Files in archive:")
for n in wb.namelist():
    print(" ", n)

# workbook.xml -> sheets
wbxml = ET.fromstring(wb.read("xl/workbook.xml"))
rels = ET.fromstring(wb.read("xl/_rels/workbook.xml.rels"))
rel_map = {}
for rel in rels:
    rid = rel.get("{%s}Id" % NS["r"])
    target = rel.get("Target")
    rel_map[rid] = target

sheets = []
for s in wbxml.find("m:sheets", NS):
    name = s.get("name")
    rid = s.get("{%s}id" % NS["r"])
    sheets.append((name, rel_map.get(rid)))

# shared strings
shared = []
try:
    sst = ET.fromstring(wb.read("xl/sharedStrings.xml"))
    for si in sst.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter() if t.tag.endswith("}t") and t.text)
        shared.append(text)
except KeyError:
    pass

print("\nShared strings count:", len(shared))

for name, target in sheets:
    path = "xl/" + target.lstrip("/")
    if not path.startswith("xl/"):
        path = "xl/" + path
    root = ET.fromstring(wb.read(path))
    print(f"\n=== Sheet: {name} ===")
    rows = {}
    for c in root.iter("{%s}c" % NS["m"]):
        ref = c.get("r")
        t = c.get("t")
        v = None
        f = None
        for child in c:
            tag = child.tag.split("}")[-1]
            if tag == "v":
                v = child.text
            elif tag == "f":
                f = child.text
        if v is None and f is None:
            continue
        if t == "s":
            val = shared[int(v)]
        elif t == "str" or t == "inlineStr":
            val = v
        elif t == "b":
            val = v == "1"
        else:
            val = v
        ri = row_idx(ref)
        ci = col_to_idx(ref)
        rows.setdefault(ri, {})[ci] = (ref, val, f)

    for ri in sorted(rows):
        cells = [rows[ri][ci] for ci in sorted(rows[ri])]
        print("row", ri + 1, cells)

